  </style>
  <script type="module">
    /* 格式化对象为HTML的辅助函数 */
    function formatObjectToHTML(obj, isDanger = false) {
      if (!obj || Object.keys(obj).length === 0) return '<div class="data-value" style="border:none;">无</div>';
      let html = '<div class="nested-box">';
      Object.entries(obj).forEach(([key, value]) => {
        let valStr = typeof value === 'object' ? JSON.stringify(value) : value;
        let valClass = isDanger ? 'accent-red' : 'data-value';
        html += `<div class="data-row" style="border:none;"><span class="data-label">${key}:</span><span class="${valClass}">${valStr}</span></div>`;
      });
      html += '</div>';
      return html;
    }

    /* 格式化剧情线：进行中（高亮）+ 已了结（灰） */
    function formatStory(story) {
      const cur = String((story && story.当前) || '').trim();
      const done = (story && Array.isArray(story.已完成)) ? story.已完成.filter(Boolean) : [];
      let html = '';
      if (cur) {
        html += `<div class="data-row" style="border:none;"><span class="data-label">进行中:</span><span class="data-value accent-red" style="font-weight:bold;">${cur}</span></div>`;
      } else if (!done.length) {
        html += '<div class="data-value" style="border:none;">无</div>';
      }
      if (done.length) {
        html += `<div class="data-row" style="border:none;"><span class="data-label">已了结:</span><span class="data-value" style="opacity:.62;">${done.join('、')}</span></div>`;
      }
      return html;
    }

    /* 格式化武学面板 (主角和NPC通用) */
    function formatMartialArts(arts) {
      if (!arts || Object.keys(arts).length === 0) return '<div class="data-value" style="border:none;">未修绝学</div>';
      let html = '<div class="nested-box">';
      Object.entries(arts).forEach(([name, data]) => {
        let badgeClass = (data.评级 === '后天' || data.评级 === '先天') ? 'badge red' : 'badge';
        html += `
          <div class="nested-item">
            <div style="font-weight:bold; color:#111; font-size:1.1em; text-shadow:1px 1px 1px rgba(255,255,255,0.8);">${name} <span class="badge">${data.类型 || '未知'}</span> <span class="${badgeClass}">${data.评级 || '未知'}</span> <span class="badge">${data.熟练度 || '未知'}</span></div>
            <div style="font-size:0.95em; color:#444; font-family:'STKaiti', serif; margin-top:4px; text-shadow:1px 1px 1px rgba(255,255,255,0.7);">${data.特殊效果 || '无'}</div>
          </div>
        `;
      });
      html += '</div>';
      return html;
    }

    /* 格式化意境面板 (主角和NPC通用) */
    function formatIntent(intents) {
      if (!intents || Object.keys(intents).length === 0) return '<div class="data-value" style="border:none;">未领悟</div>';
      let html = '<div class="nested-box">';
      Object.entries(intents).forEach(([name, data]) => {
        html += `
          <div class="nested-item">
            <div    style="font-weight:bold; color:#111; font-size:1.1em; text-shadow:1px 1px 1px rgba(255,255,255,0.8);">${name} <span class="badge red">${data.境界 || '未知'}</span></div>
            <div style="font-size:0.95em; color:#444; font-family:'STKaiti', serif; margin-top:4px; text-shadow:1px 1px 1px rgba(255,255,255,0.7);">${data.特殊效果 || '无'}</div>
          </div>
        `;
      });
      html += '</div>';
      return html;
    }

    /* 格式化宠物栏 (主角) */
    function formatPets(pets) {
      if (!pets || Object.keys(pets).length === 0) return '<div class="data-value" style="border:none;">未豢养灵宠</div>';
      let html = '<div class="nested-box">';
      Object.entries(pets).forEach(([name, data]) => {
        let badgeClass = (data.等阶 === '后天' || data.等阶 === '一品') ? 'badge red' : 'badge';
        html += `
          <div class="nested-item">
            <div style="font-weight:bold; color:#111; font-size:1.1em; text-shadow:1px 1px 1px rgba(255,255,255,0.8);">${name} <span class="${badgeClass}">${data.等阶 || '不入流'}</span> <span class="badge">${data.等级 || '初驯'}</span></div>
            <div style="font-size:0.95em; color:#444; font-family:'STKaiti', serif; margin-top:4px; text-shadow:1px 1px 1px rgba(255,255,255,0.7);">亲密度 ${data.好感度 || 0}｜${data.能力 || '无'}</div>
          </div>
        `;
      });
      html += '</div>';
      return html;
    }

    /* 格式化天材地宝栏 (主角) */
    function formatTreasures(treasures) {
      if (!treasures || Object.keys(treasures).length === 0) return '<div class="data-value" style="border:none;">暂无奇珍</div>';
      let html = '<div class="nested-box">';
      Object.entries(treasures).forEach(([name, data]) => {
        let badgeClass = (data.品级 === '先天' || data.品级 === '后天') ? 'badge red' : 'badge';
        html += `
          <div class="nested-item">
            <div style="font-weight:bold; color:#111; font-size:1.1em; text-shadow:1px 1px 1px rgba(255,255,255,0.8);">${name} <span class="${badgeClass}">${data.品级 || '一品'}</span> <span class="badge">${data.状态 || '持有'}</span></div>
            <div style="font-size:0.95em; color:#444; font-family:'STKaiti', serif; margin-top:4px; text-shadow:1px 1px 1px rgba(255,255,255,0.7);">${data.效果 || '无'}</div>
          </div>
        `;
      });
      html += '</div>';
      return html;
    }

    /* 格式化单个NPC的伤势栏（二级面板内三级内容） */
    function formatNpcInjuries(body) {
      if (!body || (!Object.keys(body.外伤 || {}).length && !Object.keys(body.内伤 || {}).length && !Object.keys(body.毒伤 || {}).length)) {
        return '<div class="data-value" style="border:none;">周身无恙</div>';
      }
      return '<div class="nested-box">'
        + '<div class="data-label" style="font-size:0.95em;">外伤:</div>' + formatObjectToHTML(body.外伤, true)
        + '<div class="data-label" style="font-size:0.95em;">内伤:</div>' + formatObjectToHTML(body.内伤, true)
        + '<div class="data-label" style="font-size:0.95em;">毒伤:</div>' + formatObjectToHTML(body.毒伤, true)
        + '</div>';
    }

    /* 格式化单个NPC的物品栏（二级面板内三级内容） */
    function formatNpcItems(items) {
      if (!items || Object.keys(items).length === 0) return '<div class="data-value" style="border:none;">两袖清风</div>';
      let html = '<div class="nested-box">';
      Object.entries(items).forEach(([k, v]) => {
        html += `<div class="data-row" style="border:none;"><span class="data-label">${k} x${v.数量 || 1}:</span><span class="data-value" style="font-size:0.95em;">${v.描述 || ''}</span></div>`;
      });
      html += '</div>';
      return html;
    }

    /* 格式化单个NPC详情卡片（含伤势/物品栏二级面板） */
    function formatNpcCard(name, data, cat) {
      let relationClass = data.好感度数值 < 0 ? 'accent-red' : '';
      let realm = data.武道境界 || '未知';

      /* 提取并格式化NPC的武器、防具、武学、意境 */
      const weaponData = data.使用武器 || {};
      let weaponHtml = weaponData.名称
        ? `<div style="text-align:right; margin-bottom:10px;">${weaponData.名称} <span class="badge">${weaponData.评级 || '不入流'}</span><br><span style="font-size:0.9em;color:#444;font-family:'STKaiti', serif;text-shadow:1px 1px 1px rgba(255,255,255,0.7);">${weaponData.特殊效果 || '无'}</span></div>`
        : '<div class="data-value" style="border:none; margin-bottom:10px;">空手</div>';

      const armorData = data.防具 || {};
      let armorHtml = armorData.名称
        ? `<div style="text-align:right; margin-bottom:10px;">${armorData.名称} <span class="badge">${armorData.评级 || '不入流'}</span><br><span style="font-size:0.9em;color:#444;font-family:'STKaiti', serif;text-shadow:1px 1px 1px rgba(255,255,255,0.7);">${armorData.特殊效果 || '无'}</span></div>`
        : '<div class="data-value" style="border:none; margin-bottom:10px;">无</div>';

      const npcArts = data.武学与意境面板 || {};
      let martialHtml = formatMartialArts(npcArts.掌握武学);
      let intentHtml = formatIntent(npcArts.领悟之意);

      return `
          <div class="nested-item" style="border-bottom: 1px solid rgba(0,0,0,0.15); padding-bottom: 10px;">
            <div class="npc-header">
              <span>${name} <span style="font-size:0.85em;font-weight:normal;color:#555;">[${data.江湖绰号 || '无名'}]</span><button class="npc-presence ${(data.在场 === '离场') ? 'off' : 'on'}" data-cat="${cat}" data-name="${String(name).replace(/"/g, '&quot;')}" title="点击切换在场/离场：离场者不加载性格调色盘，省 token">${(data.在场 === '离场') ? '离场' : '在场'}</button> <button class="npc-del" data-cat="${cat}" data-name="${String(name).replace(/"/g, '&quot;')}">除名</button></span>
              <span style="font-size:0.85em;font-weight:normal;color:#555;">${data.所属势力 || '无门无派'} ▼</span>
            </div>
            <div class="npc-content">
              <div class="data-row" style="border:none; margin-bottom:4px;"><span class="data-label">境界:</span><span class="data-value">${realm}</span></div>
              <div class="data-row" style="border:none; margin-bottom:4px;"><span class="data-label">年龄:</span><span class="data-value">${data.年龄 || '不详'}</span></div>
              <div class="data-row" style="border:none; margin-bottom:4px;"><span class="data-label">羁绊:</span><span class="${relationClass} data-value">${data.好感度阶段 || '未知'} (${data.好感度数值 || 0})</span></div>
              <div class="data-row" style="border:none; margin-bottom:4px;"><span class="data-label">在场:</span><span class="data-value">${(data.在场 === '离场') ? '离场（不加载性格调色盘）' : '在场'}</span></div>
              <div class="data-row" style="border:none; margin-bottom:4px;"><span class="data-label">恩怨:</span><span class="data-value" style="font-size:0.9em;">${data.恩怨简述 || '无'}</span></div>
              <div class="data-row" style="border:none; margin-bottom:10px;"><span class="data-label">心声:</span><span class="data-value" style="font-size:0.9em; color:#333; font-style:italic;">「${data.内心话 || '...'}」</span></div>

              <div class="data-label" style="font-weight:bold; margin-bottom:4px;">兵刃:</div>
              ${weaponHtml}

              <div class="data-label" style="font-weight:bold; margin-bottom:4px;">护身宝甲:</div>
              ${armorHtml}

              <div class="sub-panel-title">沉疴伤势<span class="sub-arrow">▼</span></div>
              <div class="sub-panel-content">${formatNpcInjuries(data.身体状态)}</div>

              <div class="sub-panel-title">随身行囊<span class="sub-arrow">▼</span></div>
              <div class="sub-panel-content">${formatNpcItems(data.物品栏)}</div>

              <div class="sub-panel-title">天材地宝<span class="sub-arrow">▼</span></div>
              <div class="sub-panel-content">${formatTreasures(data.天材地宝栏)}</div>

              <div class="sub-panel-title">豢养灵宠<span class="sub-arrow">▼</span></div>
              <div class="sub-panel-content">${formatPets(data.宠物栏)}</div>

              <div class="data-label" style="font-weight:bold; margin-bottom:4px;">修习绝学:</div>
              ${martialHtml}

              <div class="data-label" style="font-weight:bold; margin-bottom:4px;">所悟之意:</div>
              ${intentHtml}
            </div>
          </div>
        `;
    }

    /* 格式化某一栏NPC列表 */
    function formatNpcCategory(cat, npcs) {
      if (!npcs || Object.keys(npcs).length === 0) return '<div class="data-value" style="border:none; padding:8px 0;">此栏暂无江湖交集</div>';
      let html = '<div class="nested-box">';
      Object.entries(npcs).forEach(([name, data]) => {
        html += formatNpcCard(name, data, cat);
      });
      html += '</div>';
      return html;
    }

    /* ===== [v4] NPC 四宫格渲染与切换 ===== */
    let currentNpcCat = null;
    function renderNpcSection(npcs) {
      const cats = ['内眷', '同门', '同道', '仇敌'];
      cats.forEach(cat => {
        const list = (npcs && npcs[cat]) || {};
        const count = Object.keys(list).length;
        const 在场数 = Object.keys(list).filter(function (k) { return (list[k] || {}).在场 !== '离场'; }).length;
        $(`.npc-cell[data-cat="${cat}"] .npc-count`).text('在场 ' + 在场数 + ' / 共 ' + count + ' 人');
      });
      if (currentNpcCat) {
        $('#npc-cat-title').text(currentNpcCat);
        $('#npc-cat-list').html(formatNpcCategory(currentNpcCat, (npcs || {})[currentNpcCat]));
      }
    }
    function openNpcCat(cat) {
      currentNpcCat = cat;
      $('#npc-cat-title').text(cat);
      const npcs = _.get(getAllVariables(), 'stat_data.登场人物', {});
      $('#npc-cat-list').html(formatNpcCategory(cat, npcs[cat]));
      $('#npc-grid').hide();
      $('#npc-category').show();
    }
    function backToNpcGrid() {
      currentNpcCat = null;
      $('#npc-category').hide();
      $('#npc-grid').show();
    }

    /* ===== [v4] 大凉地图：地点 → 光点坐标映射（百分比，可标定校准） ===== */
    const MAP_POINTS = {
      '宸州':      { x: 41.27, y: 37.29 },
      '锦州':      { x: 63.48, y: 36.66 },
      '禹州':      { x: 28.91, y: 51.9 },
      '岳州':      { x: 40.85, y: 65.57 },
      '燕州':      { x: 51.12, y: 20.01 },
      '蓟州':      { x: 75.84, y: 16.86 },
      '凉州':      { x: 25.56, y: 19.54 },
      '楚州':      { x: 60.96, y: 55.99 },
      '蜀州':      { x: 18.44, y: 66.2 },
      '黔州':      { x: 30.06, y: 74.37 },
      '海州':      { x: 66.52, y: 75.63 },
      '晋州':      { x: 58.41, y: 23.85 },
      '琼州':      { x: 82.8, y: 87.34 },
      '金月部落':    { x: 48.08, y: 3.67 },
      '草头戎':     { x: 47.87, y: 10.58 },
      '高丽':      { x: 92.7, y: 24.41 },
      '东瀛':      { x: 90.92, y: 64.63 },
      '蓬莱':      { x: 84.33, y: 77.94 },
      '南洋群岛':    { x: 94.58, y: 93.61 },
      '南疆':      { x: 12.36, y: 84.74 },
      '西域':      { x: 7.75, y: 31.01 },
      '大梦教':     { x: 11.84, y: 9.95 },
      '罗刹国':     { x: 80.28, y: 8.25 }
    };
    /* 解析优先级：州 > 周边势力（避免子串误匹配） */
    const MAP_ORDER = ['宸州', '锦州', '禹州', '岳州', '燕州', '蓟州', '凉州', '楚州', '蜀州', '黔州', '海州', '晋州', '琼州', '金月部落', '草头戎', '高丽', '东瀛', '蓬莱', '南洋群岛', '南疆', '西域', '大梦教', '罗刹国'];
    function renderMapPoint(loc) {
      $('#map-loc').text(loc || '所在何方');
      let hit = null;
      if (loc) {
        for (const key of MAP_ORDER) {
          if (loc.indexOf(key) !== -1) { hit = MAP_POINTS[key]; break; }
        }
      }
      if (hit) {
        $('#map-dot').css({ left: hit.x + '%', top: hit.y + '%' }).show();
      } else {
        $('#map-dot').hide();
      }
    }

    /* 生成转赠目标NPC下拉选项（四栏人物） */
    function npcTargetOptions() {
      const all = getAllVariables();
      const npcs = _.get(all, 'stat_data.登场人物', {});
      let html = '<option value="">转赠与…</option>';
      ['内眷', '同门', '同道', '仇敌'].forEach(cat => {
        const list = npcs[cat] || {};
        Object.keys(list).forEach(name => {
          html += `<option value="${cat}/${String(name).replace(/"/g, '&quot;')}">${cat}·${name}</option>`;
        });
      });
      return html;
    }

    /* 渲染数据到DOM */
    function populateCharacterData() {
      let all_variables = {};
      try { all_variables = Mvu.getMvuData({ type: 'message', message_id: getCurrentMessageId() }) || getAllVariables(); }
      catch (e) { all_variables = getAllVariables(); }
      const world = _.get(all_variables, 'stat_data.世界', {});
      const hero = _.get(all_variables, 'stat_data.主角', {});
      const npcs = _.get(all_variables, 'stat_data.登场人物', {});

      /* 世界模块 */
      $('#w-time').text(world.当前时间 || '未知');
      $('#w-loc').text(world.当前地点 || '未知');
      $('#w-rumors').html(formatObjectToHTML(world.江湖传闻));
      renderMapPoint(world.当前地点);

      /* 主角基础信息 */
      const base = hero.基础信息 || {};
      $('#h-name').text(base.姓名 || '未知');
      $('#h-age').text(base.年龄 || '未知');
      $('#h-faction').text(base.所属势力 || '无');
      $('#h-status').text(base.势力地位 || '无');

      let realm = base.武道境界 || '无修为';
      let realmClass = (realm.includes('抱丹') || realm.includes('破星')) ? 'accent-red' : '';
      $('#h-realm').html(`<span class="${realmClass}">${realm}</span>`);

      $('#h-title').text(base.江湖绰号 || '无');
      $('#h-fame').text(base.武林声望 || '默默无闻');
      $('#h-rank').text(`天:${base.天榜排名 || '未入榜'} | 地:${base.地榜排名 || '未入榜'} | 人:${base.人榜排名 || '未入榜'}`);

      /* 身体状态 (红色预警) */
      const body = hero.身体状态 || {};
      $('#h-wound-ext').html(formatObjectToHTML(body.外伤, true));
      $('#h-wound-int').html(formatObjectToHTML(body.内伤, true));
      $('#h-wound-tox').html(formatObjectToHTML(body.毒伤, true));

      /* 财富与装备 */
      const wealth = hero.财富资源 || {};
      const money = wealth.银钱 || {};
      $('#h-money').text((money.两 || 0) + ' 两 ' + (money.文 || 0) + ' 文');
      $('#h-property').html(formatObjectToHTML(wealth.产业));

      const equip = hero.装备栏 || {};
      const weapon = equip.主武器 || {};
      $('#h-weapon').html(`${weapon.名称 || '空手'} <span class="badge">${weapon.评级 || '不入流'}</span><br><span style="font-size:0.9em;color:#444;font-family:'STKaiti', serif;text-shadow:1px 1px 1px rgba(255,255,255,0.7);">${weapon.特殊效果 || '无'}</span>`);
      const armor = equip.防具 || {};
      $('#h-armor').html(armor.名称
        ? `${armor.名称} <span class="badge">${armor.评级 || '不入流'}</span><br><span style="font-size:0.9em;color:#444;font-family:'STKaiti', serif;text-shadow:1px 1px 1px rgba(255,255,255,0.7);">${armor.特殊效果 || '无'}</span>`
        : '无');
      $('#h-special').html(formatObjectToHTML(equip.特殊道具));

      /* 武学百艺与奇遇 */
      const martial = hero.武学与意境面板 || {};
      $('#h-arts').html(formatMartialArts(martial.掌握武学));
      $('#h-intent').html(formatIntent(martial.领悟之意)); /* 使用专属意境格式化 */

      /* 宠物与天材地宝（置于功法栏之上） */
      $('#h-pets').html(formatPets(hero.宠物栏));
      $('#h-treasures').html(formatTreasures(hero.天材地宝栏));

      const arts = hero.百艺面板 || {};
      $('#h-crafts').html(formatObjectToHTML(arts.掌握技艺));

      const quest = hero.奇遇与目标 || {};
      $('#h-quest').html(formatObjectToHTML(quest.当前任务));
      $('#h-clue').html(formatObjectToHTML(quest.奇遇线索));

      /* 剧情线（与任务/奇遇同属「江湖因果」段） */
      const story = _.get(all_variables, 'stat_data.剧情线', {}) || {};
      $('#h-story').html(formatStory(story));

      /* 背包（含删除/转赠NPC操作） */
      const items = hero.物品栏 || {};
      let itemsHtml = '<div class="nested-box">';
      if(Object.keys(items).length === 0) itemsHtml += '<div class="data-value" style="border:none;">空空如也</div>';
      Object.entries(items).forEach(([k, v]) => {
        itemsHtml += `
          <div class="nested-item" style="border-bottom:1px dashed rgba(0,0,0,0.15); padding-bottom:6px; margin-bottom:6px;">
            <div class="data-row" style="border:none;"><span class="data-label">${k} x${v.数量 || 1}:</span><span class="data-value" style="font-size:0.95em;">${v.描述 || ''}</span></div>
            <div class="item-ops">
              <select class="item-target" data-item="${String(k).replace(/"/g, '&quot;')}">${npcTargetOptions()}</select>
              <button class="item-btn item-give" data-item="${String(k).replace(/"/g, '&quot;')}">转赠</button>
              <button class="item-btn danger item-del" data-item="${String(k).replace(/"/g, '&quot;')}">弃置</button>
            </div>
          </div>`;
      });
      itemsHtml += '</div>';
      $('#h-items').html(itemsHtml);

      /* NPC四宫格 */
      renderNpcSection(npcs);
    }

    async function init() {
      await waitGlobalInitialized('Mvu');
      populateCharacterData()
      buildQunfang();;

      /* 监听变量更新事件 */
      eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, () => {
        populateCharacterData();
      });

      /* 一级折叠面板逻辑：再次点击标题可折叠回去 */
      $('.section-title').on('click', function () {
        const $content = $(this).next('.collapsible-content');
        $content.stop(true, true).slideToggle('fast', function () {
          /* 动画结束后同步 active 类，保证 CSS 状态与显示状态一致 */
          $content.toggleClass('active', $content.is(':visible'));
        });
        $(this).toggleClass('active');
      });

      /* [v2] 卷轴展开（初始 display:none 不占位，展开时先显示再播放动画） */
      let rollerHideTimer = null, wrapHideTimer = null;
      $('#scrollRoller').on('click', function () {
        clearTimeout(wrapHideTimer);
        $(this).addClass('rolled-out');
        const $wrap = $('#scrollWrap');
        $wrap.css('display', 'block');
        requestAnimationFrame(() => requestAnimationFrame(() => {
          $wrap.addClass('expanded');
        }));
        rollerHideTimer = setTimeout(() => { $('#scrollRoller').css('display', 'none'); }, 600);
        $('#scrollCollapse').show();
      });

      /* [v3] 卷轴收拢：点击按钮缩回最初卷轴形态 */
      $('#scrollCollapse').on('click', function () {
        clearTimeout(rollerHideTimer);
        const $wrap = $('#scrollWrap');
        const $roller = $('#scrollRoller');
        $wrap.removeClass('expanded');
        $(this).hide();
        $('.page-tab').removeClass('active');
        $('.page-tab[data-page="status"]').addClass('active');
        $('.page-container').removeClass('active');
        $('.page-container[data-page="status"]').addClass('active');
        $roller.css('display', 'flex');
        requestAnimationFrame(() => requestAnimationFrame(() => {
          $roller.removeClass('rolled-out');
        }));
        wrapHideTimer = setTimeout(() => { $wrap.css('display', 'none'); }, 800);
      });

      /* [v2] 黑夜模式切换 */
      function applyTheme(dark) {
        $('body').toggleClass('dark', !!dark);
        $('#themeToggle').text(dark ? '☀' : '🌙');
        try { localStorage.setItem('dljh-theme', dark ? 'dark' : 'light'); } catch (e) {}
      }
      let savedTheme = null;
      try { savedTheme = localStorage.getItem('dljh-theme'); } catch (e) {}
      applyTheme(savedTheme === 'dark');
      $('#themeToggle').on('click', function () {
        applyTheme(!$('body').hasClass('dark'));
      });

      /* [v3.1] NPC 在场/离场切换：写回变量，离场者不加载性格调色盘 */
      $('#npc-cat-list').on('click', '.npc-presence', async function (e) {
        e.stopPropagation();
        const cat = $(this).data('cat'), name = $(this).data('name');
        try {
          const all = getAllVariables();
          const npc = _.get(all, 'stat_data.登场人物.' + cat + '.' + name, null);
          if (!npc) return;
          const 新值 = (npc.在场 === '离场') ? '在场' : '离场';
          _.set(all, 'stat_data.登场人物.' + cat + '.' + name + '.在场', 新值);
          await Mvu.replaceMvuData(all, { type: 'message', message_id: getCurrentMessageId() });
          populateCharacterData();
        } catch (err) { console.error('切换在场状态失败', err); }
      });

      /* [v2] NPC 除名：删除 stat_data.登场人物 指定栏中指定人物 */
      async function deleteNpc(cat, name) {
        if (!window.confirm('确定将「' + name + '」从江湖名录中除名？该人物变量将一并清除。')) return;
        try {
          const all = getAllVariables();
          const npcs = _.get(all, 'stat_data.登场人物', {});
          if (!npcs[cat] || !npcs[cat][name]) return;
          delete npcs[cat][name];
          await Mvu.replaceMvuData(all, { type: 'message', message_id: getCurrentMessageId() });
          populateCharacterData();
        } catch (err) { console.error('除名失败', err); }
      }
      $('#npc-cat-list').on('click', '.npc-del', function (e) {
        e.stopPropagation();
        deleteNpc($(this).data('cat'), $(this).data('name'));
      });

      /* NPC二级折叠面板逻辑：再次点击可折叠回去 (事件委托) */
      $('#npc-cat-list').on('click', '.npc-header', function() {
        $(this).next('.npc-content').stop(true, true).slideToggle('fast');
      });

      /* [v4] 二级面板展开/收起（功法/天材地宝/宠物/NPC伤势/物品栏，事件委托） */
      $('.ink-scroll').on('click', '.sub-panel-title', function () {
        $(this).toggleClass('open');
        $(this).next('.sub-panel-content').stop(true, true).slideToggle('fast', function () {
          $(this).toggleClass('open', $(this).is(':visible'));
        });
      });

      /* [v4] NPC 四宫格切换：点格进入对应栏 */
      $('#npc-grid').on('click', '.npc-cell', function () {
        openNpcCat($(this).data('cat'));
      });
      $('#npcBack').on('click', backToNpcGrid);

      /* [v4] 按 X 键返回四宫格 */
      $(document).on('keydown', function (e) {
        if (!currentNpcCat) return;
        if ($(e.target).is('input, textarea, select')) return;
        if (e.key === 'x' || e.key === 'X') {
          e.preventDefault();
          backToNpcGrid();
        }
      });

      /* [v4] 物品弃置：直接从 stat_data.主角.物品栏 删除 */
      $('#h-items').on('click', '.item-del', async function () {
        const item = $(this).data('item');
        if (!window.confirm('确定弃置「' + item + '」？将直接从行囊变量中删除。')) return;
        try {
          const all = getAllVariables();
          const hero = _.get(all, 'stat_data.主角', {});
          if (!hero.物品栏 || !hero.物品栏[item]) return;
          delete hero.物品栏[item];
          await Mvu.replaceMvuData(all, { type: 'message', message_id: getCurrentMessageId() });
          populateCharacterData();
        } catch (err) { console.error('弃置物品失败', err); }
      });

      /* [v4] 物品转赠：移入某NPC（四栏）的物品栏 */
      $('#h-items').on('click', '.item-give', async function () {
        const item = $(this).data('item');
        const target = $(this).closest('.nested-item').find('.item-target').val();
        if (!target) { window.alert('请先选择要转赠的江湖人物。'); return; }
        const slash = target.indexOf('/');
        const cat = target.slice(0, slash);
        const npcName = target.slice(slash + 1);
        if (!window.confirm('确定将「' + item + '」转赠给【' + cat + '·' + npcName + '】？该物品将移入对方行囊。')) return;
        try {
          const all = getAllVariables();
          const hero = _.get(all, 'stat_data.主角', {});
          const npcs = _.get(all, 'stat_data.登场人物', {});
          if (!hero.物品栏 || !hero.物品栏[item]) return;
          if (!npcs[cat] || !npcs[cat][npcName]) { window.alert('未找到该人物，可能已被除名。'); return; }
          const entry = hero.物品栏[item];
          npcs[cat][npcName].物品栏 = npcs[cat][npcName].物品栏 || {};
          npcs[cat][npcName].物品栏[item] = entry;
          delete hero.物品栏[item];
          await Mvu.replaceMvuData(all, { type: 'message', message_id: getCurrentMessageId() });
          populateCharacterData();
        } catch (err) { console.error('转赠物品失败', err); }
      });
    }

    /* ===== [v4] 地图展卷弹窗 ===== */
    var mapScale = 1.0;
    /* 舆图原始宽高比（弹窗按此定高，保证 % 坐标光点与图对齐） */
    function mapAspect() {
      var im = document.querySelector('.ink-scroll .map-box img');
      var a = im && im.naturalWidth && im.naturalHeight ? (im.naturalWidth / im.naturalHeight) : (4 / 3);
      return a;
    }
    function toggleMapOverlay() {
      var $overlay = $('#mapOverlay');
      if ($overlay.hasClass('active')) {
        $overlay.removeClass('active');
        return;
      }
      // 定位弹窗到原地图位置
      var $box = $('.ink-scroll .map-box');
      var boxOffset = $box.offset();
      var boxW = $box.width();
      // 弹窗宽度 = 原地图宽度，位置 = 原地图位置
      $('#mapPopup').css({
        top: boxOffset.top + 'px',
        left: boxOffset.left + 'px',
        width: boxW + 'px',
        height: Math.round(boxW / mapAspect()) + 'px'
      });
      // 克隆当前地图到弹窗
      var $origImg = $('.ink-scroll .map-box img');
      var $origDot = $('#map-dot');
      $('#mapOverlayImg').attr('src', $origImg.attr('src'));
      if ($origDot.is(':visible')) {
        $('#mapOverlayDot').css({ display: 'block', left: $origDot[0].style.left, top: $origDot[0].style.top });
      } else {
        $('#mapOverlayDot').hide();
      }
      mapScale = 1.0;
      $('#mapPopup').css('transform', 'scale(1)');
      $overlay.addClass('active');
    }
    $('#mapExpandBtn').on('click', function (e) { e.stopPropagation(); toggleMapOverlay(); });
    $('#mapOverlayClose').on('click', toggleMapOverlay);
    $('#mapOverlay').on('click', function (e) { if (e.target === this) toggleMapOverlay(); });
    $('#mapZoomIn').on('click', function (e) {
      e.stopPropagation();
      mapScale = Math.min(mapScale + 0.25, 4.0);
      $('#mapPopup').css('transform', 'scale(' + mapScale + ')');
    });
    $('#mapZoomOut').on('click', function (e) {
      e.stopPropagation();
      mapScale = Math.max(mapScale - 0.25, 0.5);
      $('#mapPopup').css('transform', 'scale(' + mapScale + ')');
    });
    // 拖拽调整大小（拖弹窗右下角）
    (function () {
      var dragging = false, sx = 0, sy = 0, sw = 0, sh = 0;
      $('#mapResizeHandle').on('mousedown', function (e) {
        e.stopPropagation();
        dragging = true; sx = e.clientX; sy = e.clientY;
        var $p = $('#mapPopup');
        sw = $p.width(); sh = $p.height();
        e.preventDefault();
      });
      $(document).on('mousemove', function (e) {
        if (!dragging) return;
        var $p = $('#mapPopup');
        var nw = Math.max(200, sw + (e.clientX - sx));
        $p.css({ width: nw + 'px', height: Math.round(nw / mapAspect()) + 'px' });
      });
      $(document).on('mouseup', function () { dragging = false; });
    })();
    // 拖拽移动弹窗位置（拖弹窗任意位置均可移动）
    (function () {
      var moving = false, mx = 0, my = 0, px = 0, py = 0;
      $('#mapPopup').on('mousedown', function (e) {
        if ($(e.target).is('button') || $(e.target).is('#mapResizeHandle')) return;
        e.stopPropagation();
        moving = true; mx = e.clientX; my = e.clientY;
        var $p = $('#mapPopup');
        px = parseInt($p.css('left')) || 0;
        py = parseInt($p.css('top')) || 0;
        e.preventDefault();
      });
      $(document).on('mousemove', function (e) {
        if (!moving) return;
        $('#mapPopup').css({ left: (px + e.clientX - mx) + 'px', top: (py + e.clientY - my) + 'px' });
      });
      $(document).on('mouseup', function () { moving = false; });
    })();


