/* [v3.1] 群芳谱别名：同一人的不同写法都归到同一位（敖茗 ＝ 清茗——敖茗是真武派弟子，道号清茗）
   —— 必须定义在 QUNFANG_IMAGES 之后、点击处理器之前的外层作用域，两个函数都要看得见 */
var QUNFANG_ALIAS = { '清茗': '敖茗', '敖茗': '敖茗' };
function qunfangCanon(n) { return QUNFANG_ALIAS[n] || n; }
function qunfangImg(n) {
  var c = qunfangCanon(n);
  if (QUNFANG_IMAGES[c]) return QUNFANG_IMAGES[c];
  if (QUNFANG_IMAGES[n]) return QUNFANG_IMAGES[n];
  for (var k in QUNFANG_ALIAS) { if (QUNFANG_ALIAS[k] === c && QUNFANG_IMAGES[k]) return QUNFANG_IMAGES[k]; }
  return '';
}


    function buildQunfang() {
      var $grid = $('#qunfangRegionGrid');
      var $panels = $('#qunfangRegionPanels');
      $grid.empty(); $panels.empty();
      var allVars = {};
      try { allVars = Mvu.getMvuData({ type: 'message', message_id: getCurrentMessageId() }) || getAllVariables(); }
      catch(e) { allVars = getAllVariables(); }
      var npcs = _.get(allVars, 'stat_data.登场人物', {});
      var metSet = new Set();
      ['内眷','同门','同道','仇敌'].forEach(function(cat) {
        var list = npcs[cat] || {};
        Object.keys(list).forEach(function(name) { metSet.add(name); metSet.add(qunfangCanon(name)); });
      });
      Object.entries(QUNFANG_DATA).forEach(function(pair) {
        var region = pair[0], chars = pair[1];
        $grid.append('<button class="region-btn" data-region="' + region + '">' + region + '<span class="region-count">' + chars.length + '</span></button>');
        var charHtml = '';
        chars.forEach(function(name) {
          var isMet = metSet.has(name) || metSet.has(qunfangCanon(name));
          var cls = isMet ? 'met' : 'unmet';
          charHtml += '<span class="char-name ' + cls + '" data-char="' + name + '">' + name + '</span>';
        });
        $panels.append('<div class="region-panel" data-region="' + region + '">' + charHtml + '</div>');
      });
    }
    $(document).on('click', '.region-btn', function() {
      var region = $(this).data('region');
      var $panel = $('.region-panel[data-region="' + region + '"]');
      var isOpen = $panel.hasClass('open');
      $('.region-panel').removeClass('open');
      $('.region-btn').removeClass('open');
      if (!isOpen) { $panel.addClass('open'); $(this).addClass('open'); }
    });
    $(document).on('click', '.char-name.met', function() {
      var name = $(this).data('char');
      var imgSrc = qunfangImg(name);
      if (!imgSrc) return;
      $('#portraitImg').attr('src', imgSrc);
      $('#portraitName').text(name);
      $('#portraitOverlay').addClass('active');
    });
    $('#portraitClose').on('click', function() { $('#portraitOverlay').removeClass('active'); });
    $('#portraitOverlay').on('click', function(e) { if (e.target === this) $(this).removeClass('active'); });

    $(errorCatched(init));
  </script>
