      text-shadow: 1px 1px 0 rgba(255,255,255,.55);
    }
    .roller-body::before, .roller-body::after {
      content: ''; position: absolute; top: -12px; bottom: -12px; width: 16px;
      background: radial-gradient(circle at 30% 30%, #c69a5b, #7a5522 72%);
      border-radius: 8px; box-shadow: 0 3px 8px rgba(0,0,0,.45);
    }
    .roller-body::before { left: -11px; }
    .roller-body::after { right: -11px; }
    .roller-band {
      position: absolute; left: 50%; top: -7px; bottom: -7px; width: 26px;
      transform: translateX(-50%);
      background: linear-gradient(90deg,#8c1f18,#d6453a 50%,#8c1f18);
      border-radius: 4px; box-shadow: 0 2px 6px rgba(0,0,0,.35);
