      font-family: "FangSong", "仿宋", "仿宋_GB2312", "STFangsong", "华文仿宋", serif; opacity: .85;
      animation: hintPulse 2.2s ease-in-out infinite;
    }
    @keyframes hintPulse { 0%,100% { opacity: .4; } 50% { opacity: 1; } }
    .ink-scroll-wrap {
      display: none;
      transform-origin: top center;
      transform: scaleY(.06); opacity: 0; pointer-events: none;
      transition: transform .7s cubic-bezier(.22,.9,.3,1), opacity .5s ease .12s;
    }
    .ink-scroll-wrap.expanded { display: block; transform: scaleY(1); opacity: 1; pointer-events: auto; }

    /* ===== [v2] NPC 除名按钮 ===== */
    .npc-del {
      margin-left: 8px; padding: 1px 8px; font-size: .78em; cursor: pointer;
      border: 1px solid #a03a30; border-radius: 4px; background: transparent; color: #a03a30;
      font-family: "FangSong", "仿宋", "仿宋_GB2312", "STFangsong", "华文仿宋", serif; transition: all .2s;
      vertical-align: middle;
    }
    .npc-del:hover { background: #a03a30; color: #fff; }
    /* ===== [v3.1] NPC 在场/离场徽标（点击切换，离场者不加载性格调色盘） ===== */
    .npc-presence { margin-left: 6px; padding: 1px 8px; font-size: .78em; cursor: pointer;
      border: 1px solid #4a7a52; border-radius: 4px; background: transparent; color: #3f6b47;
      font-family: 'Ma Shan Zheng', "STKaiti", serif; transition: all .2s; vertical-align: middle; }
    .npc-presence:hover { background: #4a7a52; color: #fff; }
    .npc-presence.off { border-color: #8a6d3b; color: #8a6d3b; opacity: .9; }
    .npc-presence.off:hover { background: #8a6d3b; color: #fff; }
    body.dark .ink-scroll .npc-presence { border-color: #6f9c78 !important; color: #b6d8bd !important; }
    body.dark .ink-scroll .npc-presence.off { border-color: #b98d4f !important; color: #e8d5a8 !important; }

    /* ===== [v2] 黑夜模式 ===== */
    body.dark .theme-toggle { background: #2c2418; color: #f0d9a8; border-color: #b98d4f; }
    body.dark .ink-scroll {
      background-color: #181410 !important;
      background-image: none !important;
      border-color: #6b5a3c !important; color: #e6dcc8 !important;
    }
    body.dark .ink-scroll .section-title { color: #f0d9a8 !important; border-color: #8a6d3b !important; }
    /* 全面覆盖：ink-scroll 内所有 div/span 文字提亮（含内联色，!important 压过内联样式） */
    body.dark .ink-scroll div, body.dark .ink-scroll span { color: #d8cbb2 !important; }
    body.dark .ink-scroll .section-title { color: #f0d9a8 !important; }
    body.dark .ink-scroll .data-label { color: #e6d9b8 !important; }
    body.dark .ink-scroll .data-value { color: #cfc3ac !important; }
    body.dark .ink-scroll .nested-box { background: rgba(255,255,255,.045) !important; border-color: #5a4c33 !important; }
    body.dark .ink-scroll .badge { background: #5a4c33 !important; color: #f0e6cf !important; }
    body.dark .ink-scroll .badge.red { background: #7a2a20 !important; color: #ffd9d0 !important; }
    body.dark .ink-scroll .accent-red { color: #ff8a7a !important; }
    body.dark .ink-scroll .npc-del { border-color: #c07a5a !important; color: #ffb4a8 !important; }
    body.dark .ink-scroll .npc-del:hover { background: #c07a5a !important; color: #1a150f !important; }
    body.dark .roller-body { background: linear-gradient(180deg,#3a3120,#2c2418 45%,#241d13) !important; border-color:#6b5a3c !important; color:#e8d5a8 !important; box-shadow: 0 5px 16px rgba(0,0,0,.55), inset 0 0 26px rgba(107,90,60,.15) !important; }
    body.dark .roller-hint { color: #b98d4f !important; }
    /* 夜间模式取消字体阴影（含 JS 生成的內联 text-shadow，一律用 !important 压掉） */
    body.dark .ink-scroll, body.dark .ink-scroll *, body.dark .ink-scroll::after,
    body.dark .roller-body, body.dark .roller-body *, body.dark .roller-hint {
      text-shadow: none !important;
