function gradeOf(item) {
  const m = item.match(/^(三品|二品|一品|后天|先天)/);
  return m ? m[1] : '';
}
function allowedGradesFor(lvl) {
  // [v3.2] 低境界严格限品：只开放能练出实战意义的档位，绝不超出《武学熟练度》的锁死上限
  if (lvl === '无修为') return [];                                  // 无武学（仅可自拟不入流把式）
  if (lvl.indexOf('一境') === 0) return ['三品'];                    // 规则允许二品仅至皮毛，界面不给
  if (lvl.indexOf('二境') === 0) return ['三品', '二品'];             // 规则允许一品仅至皮毛，界面不给
  if (lvl.indexOf('三境') === 0) return ['三品', '二品'];
  if (lvl.indexOf('四境') === 0) return ['三品', '二品', '一品'];
  if (lvl.indexOf('五境八关') === 0) return ['三品', '二品', '一品', '后天', '先天'];
  return ['三品', '二品', '一品', '后天', '先天'];
}
function currentOptions(exclude) {
  const fac = document.getElementById('faction').value;
  const lvl = document.getElementById('level').value;
  let data = factionData[fac] || {};
  if (fac === '无名小派' && window.miniHeritageSkills && window.miniHeritageSkills.length) {
    data = { all: window.miniHeritageSkills.map(function (s) {
      return { value: s.grade + ' ' + s.type + '《' + s.name + '》', text: s.grade + ' ' + s.type + '《' + s.name + '》：' + (s.desc ? s.desc.slice(0, 40) : '') };
    }) };
  }
  const list = data.all || [];
  const allowed = allowedGradesFor(lvl);
  // 特例: 武备司与大梦教残部在八关境界可选先天武学
  const isBaguan = lvl.indexOf('五境八关') === 0;
  const xiantianFactions = ['宸州 - 武备司', '凉州 - 大梦教残部'];
  if (isBaguan && xiantianFactions.indexOf(fac) >= 0) allowed.push('先天');
  return list.filter(function (it) {
    const val = (typeof it === 'object' && it !== null) ? it.value : it;
    return allowed.indexOf(gradeOf(val)) >= 0 && exclude.indexOf(val) < 0;
  });
}
function fillSelect(sel, opts, cur) {
  sel.innerHTML = '';
  const ph = document.createElement('option');
  ph.value = '';
  ph.textContent = '—— 选择武学 ——';
  sel.appendChild(ph);
  opts.forEach(function (o) {
    const op = document.createElement('option');
    if (typeof o === 'object' && o !== null) { op.value = o.value; op.textContent = o.text || o.value; }
    else { op.value = o; op.textContent = o; }
    if ((typeof o === 'object' && o !== null ? o.value : o) === cur) op.selected = true;
    sel.appendChild(op);
  });
}

