function refreshSelects() {
  try {
    const skills = [];
    for (let i = 1; i <= 6; i++) skills.push(document.getElementById('skill-' + i));
    if (skills.some(function (s) { return !s; })) return;
    const vals = skills.map(function (s) { return s.value; });
    const exclude = [];
    for (let i = 0; i < 6; i++) {
      fillSelect(skills[i], currentOptions(exclude.slice()), vals[i]);
      if (vals[i]) exclude.push(vals[i]);
