-武道底蕴: 境界【${info.level}】，武学根基【${info.skill}】。
-意境底蕴: ${info.intent || '未悟意境'}。（此为开局设定，非剧情领悟；若有值请直接登记：路径 /主角/武学与意境面板/领悟之意/{意境名}，值为 {境界, 特殊效果}，境界取 初境_意／中境_明意／上境_极意／极境_真意 之一，特殊效果详写其神异。）
-百艺底蕴: ${info.arts}。（百艺熟练度仅取一~三级；四~五级须剧情修得，见《百艺系统规则》）
-身份背景: 隶属【${info.faction}】，当前身份【${info.job}】。背景来历: ${info.bg}
${info.level === '无修为' ? '-未入武道之因: ' + (info.whyNoRealm || '（未填写）') + '。\n  交代要求：大凉武道普及，无修为者极罕见；演绎时须让此因自然体现在其体魄、举止、见识与旁人看待他的方式上（如不会吐纳、体力与恢复不如武者、对气机全无感知），不得写成深藏不露的高手。' : ''}
-资产底蕴: 银两与外物【${info.money}】；兵器与灵物【${info.gear}】。
-外貌特征: ${info.look}
-空间锚点: 大凉【${info.loc}】
-当前场景: 请生成一段沉浸式开场。${info.n}在${info.loc}遭遇以下情景：${info.scene}。请融合大凉世界观的武侠风格进行细腻的白描。
指令: 初始档案已确立，变量数据已由系统初始化，无需全量覆写。本回复专注于演绎开场剧情，不要在回复中输出 <UpdateVariable> 块——主角初始档案的变量录入（姓名/境界/所属势力/武学/银钱/装备/地点等）将由系统的额外模型解析自动完成，你只需把演绎做扎实即可。若当前未启用额外模型解析，则按《变量更新规则》在回复末尾执行一次变量更新（JSON Patch 精确到最末端字段，禁止整节点 replace，严禁重复更新）。
]`;
  return txt;
}

function sub(){
  const _lv = (document.getElementById('level') || {}).value || '';
  if (_lv === '无修为') {
    const _w = (document.getElementById('why-norealm') || {}).value || '';
    if (!_w.trim()) {
      alert('【无修为】在大凉极为罕见，请先在「为何无修为」一栏写明缘由，再行入局。');
      const _el = document.getElementById('why-norealm');
      if (_el) _el.focus();
      return;
    }
  }
  const txt = 档案文本();
  try {
    if (typeof triggerSlash === 'function') {
      triggerSlash(`/send ${txt.replace(/\n/g, ' ')} | /trigger`);
    } else if (typeof send_text_to_input === 'function') {
      send_text_to_input(txt, true);
      setTimeout(() => { const b = document.getElementById('send_textarea'); if (b) b.click() }, 200);
    } else {
      navigator.clipboard.writeText(txt).then(() => alert("卷宗已复制，请粘贴发送"));
    }
    const b = document.getElementById('btn');
    b.innerText = "已入局";
    b.disabled = true;
  } catch(e) {
    alert("录入出错");
    console.error(e);
  }
}


/* __先天矫正：预设换好后统一矫正品级 —— 只有预设中标为「先天」的那几行显示并锁死为先天，其余行一律选不到先天 */
(function () {
  function 矫正() {
    var key = (document.getElementById('preset') || {}).value || '';
    var p = (window.PRESETS || {})[key] || {};
    var 串 = p.skill || '';
    var 先天名 = [];
    串.split('、').forEach(function (part) {
      var m = part.match(/^自得奇功·(三品|二品|一品|后天|先天)[^《]*《([^》]+)》/);
      if (m && m[1] === '先天') 先天名.push(m[2]);
    });
    var 串名 = 串.split('、').map(function (part) { var m = part.match(/《([^》]+)》/); return m ? m[1] : ''; });
    var 行 = document.querySelectorAll('.cs-grade');
    for (var i = 0; i < 行.length; i++) {
      var sel = 行[i], o = sel.querySelector('option.opt-xian');
      if (!o) continue;
      var 盒 = sel.parentElement, 名框 = 盒 ? 盒.querySelector('input, textarea') : null;
      var 名 = 名框 ? (名框.value || '').trim() : '';
      if (!名) 名 = 串名[i] || '';
      if (先天名.indexOf(名) >= 0) {
        o.disabled = false; o.removeAttribute('disabled');
        sel.value = '先天';
        o.disabled = true; o.setAttribute('disabled', '');   /* 显示为先天，但改不动 */
      } else {
        if (sel.value === '先天') sel.value = '三品';
        o.disabled = true; o.setAttribute('disabled', '');
      }
    }
  }
  window.__先天矫正 = 矫正;
  document.addEventListener('change', function (e) { if (e.target && e.target.id === 'preset') setTimeout(矫正, 30); }, true);
  document.addEventListener('click', function (e) { if (e.target && e.target.id === 'btn') setTimeout(矫正, 30); }, true);
  setTimeout(矫正, 60);
})();
</script>
</body>
</html>
