// NPC 境界同步自动结算（酒馆助手脚本）
// 功能：剧情时间大幅流逝（月差≥3，约跨季）时，自动批量提升同档/低档 NPC 的小境界，
//       在 MVU 变量更新结束时直接写入 stat_data 并推进 世界.上次成长结算 锚点，
//       免除 AI 逐 NPC 手动写入的变量更新负担。
// 依赖：MVU 变量框架（Mvu）。API 不可用时静默降级（AI 可继续按《NPC境界同步成长规则》手动结算）。
$(() => {
  (async () => {
    await waitGlobalInitialized('Mvu');

    const 境界阶梯 = [
      '无修为', '一境锻骨', '二境筑基', '三境明气', '四境开窍',
      '五境八关_一关开', '五境八关_二关休', '五境八关_三关生', '五境八关_四关伤', '五境八关_五关杜',
      '五境八关_六关景', '五境八关_七关死', '五境八关_八关惊',
      '六关气海_初入', '六关气海_中凝', '六关气海_满盈',
      '七关气海_初入', '七关气海_中凝', '七关气海_满盈',
      '八关气海_初入', '八关气海_中凝', '八关气海_满盈',
      '七境抱丹', '八境破星', '九境宏愿'
    ];

    // 中文数字解析（1~99）：支持 元/正/冬/腊 等特殊写法
    function 中文数字(s) {
      if (typeof s !== 'string' || s.length === 0) return null;
      if (s === '元') return 1;
      const 单字 = { 一: 1, 二: 2, 两: 2, 三: 3, 四: 4, 五: 5, 六: 6, 七: 7, 八: 8, 九: 9, 十: 10, 正: 1, 冬: 11, 腊: 12 };
      if (s in 单字) return 单字[s];
      const 尾 = { 一: 1, 二: 2, 三: 3, 四: 4, 五: 5, 六: 6, 七: 7, 八: 8, 九: 9 };
      let m = s.match(/^十([一二三四五六七八九])$/); // 十一~十九
      if (m) return 10 + 尾[m[1]];
      m = s.match(/^([一二三四五六七八九])十$/); // 二十~九十
      if (m) return 尾[m[1]] * 10;
      m = s.match(/^([一二三四五六七八九])十([一二三四五六七八九])$/); // 二十一~九十九
      if (m) return 尾[m[1]] * 10 + 尾[m[2]];
      return null;
    }

    // 解析「大凉更启X年Y月…」为累计月数；格式无法解析时返回 null
    function 解析月(t) {
      if (typeof t !== 'string') return null;
      const 年匹配 = t.match(/([元一二三四五六七八九十两]{1,3})年/);
      const 月匹配 = t.match(/([正一二三四五六七八九十冬腊两]{1,3})月/);
      if (!月匹配) return null;
      const 年 = 年匹配 ? 中文数字(年匹配[1]) : 1;
      const 月 = 中文数字(月匹配[1]);
      if (!年 || !月) return null;
      return 年 * 12 + 月;
    }

    function 档位(b) {
      if (typeof b !== 'string') return -1;
      return 境界阶梯.indexOf(b.trim().replace(/\s+/g, ''));
    }

    // 小境界内提升；不跨大境界（五境八关逐关推进、气海在关内 初入→中凝→满盈 推进；
    // 无修为~四境开窍跨大境界需铺垫、抱丹/破星/宏愿需机缘，均不自动提升）
    function 提升(档, 步数) {
      if (档 < 0) return null;
      const b = 境界阶梯[档];
      if (b.startsWith('五境八关')) {
        const 上限 = 境界阶梯.indexOf('五境八关_八关惊');
        return 境界阶梯[Math.min(档 + 步数, 上限)];
      }
      if (b.includes('气海')) {
        const 关内 = ['初入', '中凝', '满盈'];
        const 分割 = b.split('_');
        const 新阶段 = 关内[Math.min(关内.indexOf(分割[1]) + 步数, 2)];
        return 分割[0] + '_' + 新阶段;
      }
      return null;
    }

    // 在 MVU 变量更新结束时结算：直接修改 variables，由 MVU 统一写回楼层，避免读写竞争
    function 结算(variables) {
      try {
        const 当前 = _.get(variables, 'stat_data.世界.当前时间', '');
        const 上次 = _.get(variables, 'stat_data.世界.上次成长结算', '');
        if (!当前 || 当前 === 上次) return; // 时间未变 → 不结算
        const 当前月 = 解析月(当前);
        const 上次月 = 解析月(上次);
        if (当前月 === null || 上次月 === null) return; // 时间格式无法解析 → 不乱动
        const 月差 = 当前月 - 上次月;
        if (月差 < 3) return; // 时间流逝不足 → 不结算

        const 主角档 = 档位(_.get(variables, 'stat_data.主角.基础信息.武道境界', ''));
        const 步数 = 月差 >= 24 ? 2 : 1;
        let 更新数 = 0;
        for (const 栏 of ['内眷', '同门', '同道', '仇敌']) {
          const 人物 = _.get(variables, 'stat_data.登场人物.' + 栏) || {};
          for (const 名 of Object.keys(人物)) {
            const npc = 人物[名] || {};
            const 档 = 档位(npc.武道境界);
            if (档 < 0) continue;      // 境界未知/异常，跳过
            if (档 > 主角档) continue; // 只提升同档或低档 NPC（主角档为 -1 时全部跳过）
            const 新 = 提升(档, 步数);
            if (新 && 新 !== npc.武道境界) {
              _.set(variables, 'stat_data.登场人物.' + 栏 + '.' + 名 + '.武道境界', 新);
              更新数++;
            }
          }
        }
        // 无论是否有 NPC 更新，时间已流逝即推进锚点，避免重复结算同一时段
        _.set(variables, 'stat_data.世界.上次成长结算', 当前);
        console.log('[NPC成长] 结算完成：时间推进 ' + 月差 + ' 个月，更新 NPC ' + 更新数 + ' 名');
      } catch (e) {
        console.error('[NPC成长] 结算异常（已忽略，不影响游戏）', e);
      }
    }

    eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, variables => {
      结算(variables);
    });
  })();
});

// 注入预算管理（酒馆助手脚本）v3 —— 会话基线快照版
// 目标：token 紧张时【临时】让出低优先级条目的额度，回落即还原；
//       核心条目永不禁用；且【绝不打乱作者的开关】——不擅自开启任何"本该关闭"的条目。
//
// 版本沿革与踩过的坑：
//   v1：只靠内存标志 + 回落判断。在超限状态下关掉的条目会被持久化写进世界书，
//       页面重载后仍停在 disabled → 表现为"世界书条目被永久关闭"。
//   v2：加了"加载即强制复原"，解决了永久关闭；但复原是【一律开启】——
//       作者手动关掉某条受管条目后，会被脚本重新打开，等于抹掉作者的选择。
//   v3：改为【基线快照】。首次运行把每个受管条目的 enabled 记下来当基线；
//       此后所有"复原"都只回到基线值：
//         · 基线为"关"的条目 → 永不擅自打开
//         · 基线为"开"的条目 → 只在超限时临时关，回落即按基线还原
//       快照存在会话内（内存），并尝试写入聊天元数据以增强跨刷新稳健性；
//       若环境不支持写元数据，则纯内存运行，功能不受影响。
//
// 说明：本脚本只使用 getCharWorldbookNames / getWorldbook / updateWorldbookWith /
//       getTokenCountAsync / eventOn 这几个卡内其它脚本已在用的 API。
$(() => {
  // 核心条目：任何情况下不参与禁用
  const 核心关键词 = ['剧情与扮演核心准则', '战力推演', '后台思维链', '剧情线调度', 'NPC境界同步成长', 'NPC好感度系统', '境界突破推演', '剧情线/'];
  // 低优先级按需规则：token 紧张时优先让位（"用到才需要"的规则，非每轮必需）
  const 低优先级关键词 = [
    '随机江湖武学生成规则', '武林盛会运作规则', '中小型势力生成规则', '随机江湖人物生成规则',
    '谈婚论嫁规则', '驯兽宠物规则', '百艺系统规则', '经济系统', '通缉追杀', '伤病暗疾',
    '江湖绰号系统', '武学评级与兵器评级', '天地人三榜', '奇遇获取与挑战规则', '武林声望与说书人规则',
    '海神娘娘庙会', '百艺大会', '群侠大会', '论武会', '试剑会', '道门法会', '锦州诗剑会',
    '少年英雄会', '南北武道大会', '开宗立派规则', '门派事务管理规则', '门派内部晋升规则',
    '势力演变规则'
  ];
  // 占用阈值：聊天 token 不含预设与世界书注入，故留足余量
  const 阈值 = 0.85;
  // 快照在聊天元数据里的键名
  const 快照键 = 'inject_budget_baseline';

  function 上下文() {
    try {
      if (typeof SillyTavern === 'undefined') return null;
      return typeof SillyTavern.getContext === 'function' ? SillyTavern.getContext() : SillyTavern;
    } catch (e) {
      return null;
    }
  }
  async function 估算占用() {
    try {
      const ctx = 上下文();
      if (!ctx || !ctx.maxContext || typeof ctx.getTokenCountAsync !== 'function') return null;
      const 聊天文本 = (ctx.chat || []).map(m => (m && m.mes) || '').join('\n');
      const 采样 = 聊天文本.slice(-ctx.maxContext * 2);
      const used = await ctx.getTokenCountAsync(采样);
      return { used, limit: ctx.maxContext };
    } catch (e) {
      return null;
    }
  }
  const 受管 = (名) => !核心关键词.some(k => 名.includes(k)) && 低优先级关键词.some(k => 名.includes(k));

  /* ── 基线快照 ── */
  let 基线 = null;   // { 条目名: true/false }
  function 读聊天快照() {
    try {
      const ctx = 上下文();
      const meta = ctx && ctx.chatMetadata;
      const 存 = meta && meta[快照键];
      return (存 && 存.表 && typeof 存.表 === 'object') ? 存.表 : null;
    } catch (e) { return null; }
  }
  function 写聊天快照(表) {
    try {
      const ctx = 上下文();
      if (ctx && ctx.chatMetadata) ctx.chatMetadata[快照键] = { 表 };
    } catch (e) { /* 不支持则忽略，纯内存运行 */ }
  }
  async function 建基线() {
    if (基线) return 基线;
    const 存 = 读聊天快照();
    if (存) { 基线 = 存; return 基线; }
    const 新基线 = {};
    try {
      const books = getCharWorldbookNames('current');
      const 书名单 = [books.primary, ...(books.additional || [])].filter(Boolean);
      for (const 书名 of 书名单) {
        const list = await getWorldbook(书名);
        (list || []).forEach(e => {
          const 名 = e.name || e.comment || '';
          if (受管(名)) 新基线[名] = (e.enabled !== false);
        });
      }
    } catch (e) {
      console.error('[注入预算] 建基线失败，本轮不做预算管理', e);
      基线 = {};
      return 基线;
    }
    基线 = 新基线;
    写聊天快照(新基线);
    const 关着的 = Object.keys(新基线).filter(k => !新基线[k]);
    console.log('[注入预算] 已建立会话基线：受管 ' + Object.keys(新基线).length + ' 条，'
      + '其中基线为关闭的 ' + 关着的.length + ' 条（这些永不擅自打开）');
    return 基线;
  }
  /* 某条目"本该是"的状态：有基线按基线，无基线保持原样 */
  function 基线值(名, 当前) {
    if (基线 && Object.prototype.hasOwnProperty.call(基线, 名)) return 基线[名];
    return 当前;
  }

  /* 复原：把受管条目拉回【基线值】（不是一律开启） */
  async function 复原() {
    try {
      await 建基线();
      const books = getCharWorldbookNames('current');
      const 书名单 = [books.primary, ...(books.additional || [])].filter(Boolean);
      let 变更 = 0;
      for (const 书名 of 书名单) {
        await updateWorldbookWith(书名, entries =>
          entries.map(e => {
            const 名 = e.name || e.comment || '';
            if (!受管(名)) return e;
            const 该 = 基线值(名, e.enabled !== false);
            if ((e.enabled !== false) === 该) return e;
            变更++;
            return { ...e, enabled: 该 };
          }),
        );
      }
      if (变更 > 0) console.log('[注入预算] 已按基线复原 ' + 变更 + ' 条');
    } catch (e) {
      console.error('[注入预算] 复原失败（已忽略，不影响游戏）', e);
    }
  }

  async function 管理() {
    const t = await 估算占用();
    if (!t) return;
    const 超限 = t.used > t.limit * 阈值;
    let 变更 = 0;
    try {
      await 建基线();
      const books = getCharWorldbookNames('current');
      const 书名单 = [books.primary, ...(books.additional || [])].filter(Boolean);
      for (const 书名 of 书名单) {
        await updateWorldbookWith(书名, entries =>
          entries.map(e => {
            const 名 = e.name || e.comment || '';
            if (!受管(名)) return e;                 // 核心与非受管条目：永不触碰
            const 基线开 = 基线值(名, e.enabled !== false);
            if (!基线开) return e;                   // 基线就是关的：永不擅自打开
            const 目标状态 = !超限;                   // 超限→临时关；回落→回基线（开）
            if ((e.enabled !== false) === 目标状态) return e;
            变更++;
            return { ...e, enabled: 目标状态 };
          }),
        );
      }
      if (变更 > 0) {
        console.log('[注入预算] ' + (超限
          ? '上下文紧张，临时让出低优先级条目 ' + 变更 + ' 条（回落即按基线复原）'
          : '上下文恢复，已按基线还原 ' + 变更 + ' 条'));
      }
    } catch (e) {
      console.error('[注入预算] 世界书切换失败（已忽略，不影响游戏）', e);
    }
  }

  // ① 每次加载先按基线复原一次
  复原().then(管理);
  // ② 每轮 AI 回复后重算
  eventOn(tavern_events.MESSAGE_RECEIVED, () => { 管理(); });
  // ③ 切换聊天时再复原一次
  eventOn(tavern_events.CHAT_CHANGED, () => { 基线 = null; 读基线后复原(); });
  function 读基线后复原() { 复原(); }
});

import { registerMvuSchema } from 'https://testingcf.jsdelivr.net/gh/StageDog/tavern_resource/dist/util/mvu_zod.js';

// 枚举值规范化：将 AI 输出的常见别名/口语写法/缺下划线写法修正为标准枚举值
// （对应世界书《变量更新规则》中"系统会自动修正缺下划线与常见别名"的承诺，此前 schema 并未实现，会导致整层变量更新被丢弃）
const 境界别名 = {
  无修为: '无修为', 不明: '不明',
  锻骨: '一境锻骨', 锻骨境: '一境锻骨',
  筑基: '二境筑基', 筑基境: '二境筑基',
  明气: '三境明气', 明气境: '三境明气',
  开窍: '四境开窍', 开窍境: '四境开窍',
  抱丹: '七境抱丹', 抱丹境: '七境抱丹',
  破星: '八境破星', 破星境: '八境破星',
  宏愿: '九境宏愿', 宏愿境: '九境宏愿',
  气海: '六关气海_初入', 气海境: '六关气海_初入',
};
const 规范化境界 = value => {
  if (typeof value !== 'string') return value;
  const v = value.trim().replace(/\s+/g, '');
  if (境界别名[v]) return 境界别名[v];
  const m = v.match(/^(五境八关|[六七八]关气海)_?(.+)$/);
  if (m) return m[1] + '_' + m[2];
  return v;
};
const 别名修正 = mapping => value => {
  if (typeof value !== 'string') return value;
  const v = value.trim();
  return mapping[v] ?? v;
};
const 好感度阶段修正 = 别名修正({ 莫逆: '莫逆之交' });
const 熟练度修正 = 别名修正({ 大成: '圆满' });
const 评级修正 = 别名修正({ 神兵: '后天', 神兵利器: '后天' });
const 防具评级修正 = 别名修正({ 神兵: '一品', 神兵利器: '一品', 后天: '一品', 先天: '一品' });
const 宠物等级修正 = 别名修正({ 亲近: '默契' });
const 意境境界修正 = 别名修正({ 真意: '极境_真意', 明意: '中境_明意' });

// 容错：AI 偶尔会用字符串替换整个对象节点（如 replace /掌握武学/天魔大化 为 "入室"），
// 导致 z.record 的值校验抛 "expected object, received string" 并丢弃整层更新。
// 此 preprocessor 将非对象值规整为空对象 {}，让该条目静默降级、其余数据不受牵连。
const 规整对象 = value => (value !== null && typeof value === 'object' && !Array.isArray(value)) ? value : {};
const 对象Record = (valueSchema) => z.record(z.string(), z.preprocess(规整对象, valueSchema));


// 登场人物通用结构（内眷/同门/同道/仇敌四栏共用）
const NpcSchema = z.object({
  年龄: z.union([z.coerce.number(), z.string()]).prefault('不详'),
  所属势力: z.string().prefault('未知'),
  武道境界: z.preprocess(规范化境界, z.enum(['无修为', '一境锻骨', '二境筑基', '三境明气', '四境开窍', '五境八关_一关开', '五境八关_二关休', '五境八关_三关生', '五境八关_四关伤', '五境八关_五关杜', '五境八关_六关景', '五境八关_七关死', '五境八关_八关惊', '六关气海_初入', '六关气海_中凝', '六关气海_满盈', '七关气海_初入', '七关气海_中凝', '七关气海_满盈', '八关气海_初入', '八关气海_中凝', '八关气海_满盈', '七境抱丹', '八境破星', '九境宏愿', '不明'])).prefault('不明').catch('不明'),
  江湖绰号: z.string().prefault('无'),
  核心阵营底线: z.string().prefault('未知'),
  好感度数值: z.coerce.number().transform(v => _.clamp(v, -100, 100)).prefault(0).catch(0),
  好感度阶段: z.preprocess(好感度阶段修正, z.enum(['不死不休', '剑拔弩张', '萍水相逢', '点头之交', '江湖同道', '莫逆之交', '生死与共'])).prefault('萍水相逢').catch('萍水相逢'),
  恩怨简述: z.string().prefault('无'),
  内心话: z.string().prefault('无'),
  生死: z.enum(['存活', '已死']).prefault('存活').catch('存活'),
  身体状态: z.object({
    外伤: z.record(z.string(), z.string()).prefault({}),
    内伤: z.record(z.string(), z.string()).prefault({}),
    毒伤: z.record(z.string(), z.string()).prefault({}),
  }).prefault({}),
