    function 所在州(地点) {
      if (typeof 地点 !== 'string') return '';
      for (const 州 of 州表) { if (地点.includes(州)) return 州; }
      return '';
    }
    function 抽(池) { return (池 && 池.length) ? 池[Math.floor(Math.random() * 池.length)] : ''; }

    function 结算(variables) {
      try {
        const 地点 = _.get(variables, 'stat_data.世界.当前地点', '') || '';
        const 州 = 所在州(地点);

        // 恶人骰（10%）
        let 恶人 = '';
        if (Math.random() < 0.10) {
          const 上次 = _.get(variables, 'stat_data.偶遇.上次恶人', '') || '';
          const 池 = EVIL.filter(n => n !== 上次);
          恶人 = 抽(池);
          if (恶人) _.set(variables, 'stat_data.偶遇.上次恶人', 恶人);
        }

        // 群芳骰（10%）
        let 群芳 = '';
        if (Math.random() < 0.10) {
          const 上次 = _.get(variables, 'stat_data.偶遇.上次群芳', '') || '';
          const 本州 = (FANG[州] || []).filter(n => n !== 上次);
          const 游历 = (FANG['游历'] || []).filter(n => n !== 上次);
          群芳 = 抽(本州.length ? 本州 : 游历);
          if (群芳) _.set(variables, 'stat_data.偶遇.上次群芳', 群芳);
        }

        _.set(variables, 'stat_data.偶遇.恶人', 恶人);
        _.set(variables, 'stat_data.偶遇.群芳', 群芳);
      } catch (e) {
        console.error('[随机偶遇] 结算异常（已忽略，不影响游戏）', e);
      }
    }

    eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, variables => { 结算(variables); });
  })();
});

